<span class="line"><span style="color:#61AFEF;">kubectl</span><span style="color:#98C379;"> taint</span><span style="color:#98C379;"> nodes</span><span style="color:#98C379;"> node1</span><span style="color:#98C379;"> key=value:NoSchedule</span><span style="color:#7F848E;font-style:italic;">     # 添加污点</span></span>
